command:
cd /app && python3 - <<'PY'
p='worktree_status.go'
s=open(p).read()
old='''func (w *Worktree) deleteFromIndex(idx *index.Index, path string) (plumbing.Hash, error) {
\te, err := idx.Remove(path)
\tif err != nil {
\t\treturn plumbing.ZeroHash, err
\t}

\treturn e.Hash, nil
}'''
new='''func (w *Worktree) deleteFromIndex(idx *index.Index, path string) (plumbing.Hash, error) {
\te, err := idx.Remove(path)
\tif err != nil {
\t\treturn plumbing.ZeroHash, err
\t}

\t// Remove any remaining entries (e.g. conflict stages 1/2/3) for the path.
\tremoveIndexEntries(idx, path)

\treturn e.Hash, nil
}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
gofmt -w worktree_status.go && go build ./... && go test . -run 'TestMerge|TestAdd' -count=1 2>&1 | tail -20
